from pathlib import Path
import json,hashlib
H=Path(__file__).resolve().parent
q=json.loads((H/'score_qa.json').read_text());m=json.loads((H/'execution_manifest.json').read_text());f=json.loads((H/'frozen_rule_manifest.json').read_text())
assert m['query_sha256']==f['source_hashes']['eicu_sofa_strict48.sql'] and all(q['checks'].values())
lines=['# eICU SOFA重建结果与交付','','范围：固定既有队列的隔离评分修复。未重训、未改MIMIC、未改冻结预测/qSOFA/结局/ID、未改工作稿或正式稿。AUC/CI/图表同步由parent另行完成。','',f"SQL SHA256：`{m['query_sha256']}`",f"CSV SHA256：`{q['new_csv_sha256']}`",f"CSV：`data/eicu_sofa_strict48.csv`；{q['n']}条入住、{q['patients']}名患者、{q['deaths']}次院内死亡；与冻结数据逐条ID/患者ID/结局一致。",f"只读提取耗时{m['elapsed_seconds']:.1f}秒；返回码{m['returncode']}。7类源时间越界计数均为0；完整六组件记录{q['complete_six_components_n']}，全组件缺失{q['all_components_missing_n']}。",'', '## 组件缺失与变动','', '|组件|缺失记录数|较旧缓存改变（为对照旧0编码，此列将新缺失按0）|','|---|---:|---:|']
for c,n in q['component_missing'].items():lines.append(f"|{c}|{n}|{q['changed_components'][c]}|")
d=q['total_changes'];lines += ['',f"总分改变{d['changed']}条，其中升高{d['higher']}、降低{d['lower']}；新总分范围{d['new_range'][0]}–{d['new_range'][1]}。组件NULL保留，总分最后补0，与每组件的observed标记一致。",'', '## 来源限制及敏感性','',f"通气状态4h主规则改为1h后，{q['support_1h_changed']}条总分改变。尿量generic/肾造瘘潜在重叠敏感性下，{q['uo_conservative_changed']}条总分改变。两规则在新AUC前冻结，未以性能选择。",'', '|来源QA字段|事件合计|涉及入住数|','|---|---:|---:|']
for c,x in q['source_QA'].items():lines.append(f"|{c}|{x['sum']}|{x['stays_positive']}|")
lines += ['',f"尿量单独导致renal≥3且至少一个决定最小小时估计的窗口只有一个真实测量间隔：{q['high_renal_uo_with_single_interval_determining_window_n']}条。此数不能直接解释为删除稀疏窗口后必然降分；别的低尿量窗口仍可能保持肾分。",'', '来源说明：','', '- 不使用respiratorycare伪0起止时点；4h支持时效与1h敏感性是明确操作假设，非验证过的精确通气时段。无可靠支持证据的PF不获3/4分，并保留unknown标记。','- mL/h不使用固定浓度；只有同条浓度或唯一有效明确药袋浓度才换算。无法换算的正药物记录没有伪造剂量；可确定的其它MAP/药物信息仍参与组件，因此源不完整可能低估循环严重程度。','- Epi mg/kg/min按原记录单位确定性换算；56条/10入住的源单位很大，即使字段间算术一致也不能证明床旁单位真实正确。其单独决定CV4规模见上表。','- 尿量排除outputtotal累计字段、同源最新修订去重、同流路非加性聚合；未知Nep缩写不猜流路。区间推定不等于连续完整监测；大值不以未经来源支持阈值自行裁剪。','- 无PaO2 specimen_id，FiO2依时间匹配；没有确认未记录值正常。eICU GCS直接合法总分，与MIMIC官方分项/ETT重建不同。','', '## 验证证据及边界','', '- `INDEPENDENT_SQL_REVIEW.md`与`independent_synthetic_results.json`：100项真实Postgres源替换CTE测试通过。','- `score_qa.json`：ID/患者ID/结局、整数分数范围、总分、observed flags、窗口/配对、原文件哈希及两个敏感性方向检查。','- `execution_manifest.json`：READ ONLY、SQL/CSV SHA及耗时。','- `source_manifest.json`和`frozen_rule_manifest.json`：官方源码/冻结输入及看AUC前的规则锁定。','- `METHODS_SNIPPET.md`：供作者审阅的补充方法英文草稿。','', '本交付不等于临床标准SOFA测量已完整验证，也不等于稿件可立即提交。结果仅在既有探索性跨库研究的源记录限制内使用；下游数字/图表与正式文档须另行同步验收。']
(H/'REPAIR_RESULTS.md').write_text('\n'.join(lines)+'\n')
p=H/'METHODS_SNIPPET.md';s=p.read_text();s=s.replace('实际提取/来源QA待本目录execution_manifest.json和score_qa.json','实际提取及来源QA已完成，见本目录execution_manifest.json和score_qa.json');s=s.split('## 需要在最终QA后补充的数字')[0];s+='\n\n## 最终聚合QA摘要\n\n'+f"六组件缺失：{q['component_missing']}；完整六组件{q['complete_six_components_n']}。1h通气时效敏感性改变总分{q['support_1h_changed']}条；保守尿量敏感性改变{q['uo_conservative_changed']}条。全部详细源计数见REPAIR_RESULTS.md，不省略unknown/unconverted边界。\n";p.write_text(s)
print(H/'REPAIR_RESULTS.md')
